"""Generate sql/06_gold_views.sql from the Terraform view sources (single source of truth).

Usage: python scripts/gen_view_sql.py [--check]
"""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
VIEWS = ROOT / "infra" / "terraform" / "modules" / "platform" / "views"
OUT = ROOT / "sql" / "06_gold_views.sql"


def render() -> str:
    manifest = json.loads((VIEWS / "manifest.json").read_text())
    parts = [
        "-- GENERATED by scripts/gen_view_sql.py from infra/terraform/modules/platform/views/*.sql. Do not edit.",
        "-- Replace PROJECT_ID. Views are not tenant-scoped: BI tools must filter organization_id/workspace_id",
        "-- (or sit behind row access policies / authorized views).",
    ]
    for name in [*manifest["tier1"], *manifest["tier2"]]:
        body = (VIEWS / f"{name}.sql").read_text().strip()
        body = body.replace("${project}", "PROJECT_ID").replace("${dataset}", "conversation_analytics")
        parts.append(f"CREATE OR REPLACE VIEW `PROJECT_ID.conversation_analytics.{name}` AS\n{body};")
    return "\n\n".join(parts) + "\n"


if __name__ == "__main__":
    text = render()
    if "--check" in sys.argv:
        raise SystemExit(0 if OUT.exists() and OUT.read_text() == text else "sql/06_gold_views.sql is stale; run scripts/gen_view_sql.py")
    OUT.write_text(text)
